add(19,'在直角三角形ABC中，∠C=90°，BC=8，AB=17，则sin A等于（ ）。',['8/15','15/17','8/17','17/8'],'C','A的对边为BC，斜边为AB，所以sin A=BC/AB=8/17。AC=√(17²−8²)=15>0，条件构成非退化直角三角形。','BC3改8，AB5改17，保留正弦的对边/斜边。','8/17',['8/15','15/17','8/17','17/8'],'按正弦定义辨认对边及斜边。')
add(20,'△ABC∽△DEF，对应顶点依次为A与D、B与E、C与F。若BC=15，EF=10，则AC/DF等于（ ）。',['2/3','3/2','4/9','9/4'],'B','对应边比相等，AC/DF=BC/EF=15/10=3/2。相似三角形非退化，DF、EF均正，分母非零。','对应边6、4改为15、10，明确顶点对应顺序。','15/10',['2/3','3/2','4/9','9/4'],'直接应用相似三角形对应边比例。')
add(4,'弦AB把圆周分成长度比为2∶7的两段弧。P在圆上且不同于A、B，则∠APB的度数可能为（ ）。',['40°','140°','80°或280°','40°或140°'],'D','两弧的度数为360°×2/9=80°与360°×7/9=280°。P在优弧内部时，所对劣弧给出40°；P在劣弧内部时，所对优弧给出140°。两种位置均可取且P不为端点。','弧比1∶3改为2∶7，保留优弧、劣弧对应的两种圆周角分类。','(360*2/9/2,360*7/9/2)',['(40,)','(140,)','(80,280)','(40,140)'],'需分类顶点所在两段弧，不能只取劣弧。')
