add(22,'抛物线y=−x²+4x+5与x轴交于A、B，其中A的横坐标较小，顶点为C。连接AC、BC，则tan∠CAB为（ ）。',['1/3','3','9','√10/10'],'B','−x²+4x+5=−(x−5)(x+1)，故A=(−1,0)、B=(5,0)。顶点C=(2,9)，从A到顶点的水平距离3、竖直距离9，tan∠CAB=9/3=3。A≠B且顶点不在x轴上。','抛物线由−x²−2x+3改为−x²+4x+5，明确A是左交点，重算顶点与正切。','(4**2/4+5)/(sqrt(4**2+4*5)/2)',['1/3','3','9','sqrt(10)/10'],'求根和顶点，再用直角三角形边比。')
add(23,'已知x₁<x₂，抛物线y=(x−x₁)(x−x₂)−4与x轴交于(m,0)、(n,0)，m<n。四个数的大小关系为（ ）。',['x₁<m<n<x₂','m<x₁<x₂<n','m<x₁<n<x₂','x₁<n<x₂<m'],'B','函数在x₁、x₂处均为−4<0且开口向上。判别式(x₂−x₁)²+16>0，确有两个不同实根；函数为负的区间正是(m,n)，所以m<x₁<x₂<n。','常数−1改−4，保留开口、负值点与两根相对位置推理。','(-sqrt((2-0)**2+16)/2+1,0,2,sqrt((2-0)**2+16)/2+1)',['(0,-sqrt(20)/2+1,sqrt(20)/2+1,2)','(-sqrt(20)/2+1,0,2,sqrt(20)/2+1)','(-sqrt(20)/2+1,0,sqrt(20)/2+1,2)','(0,sqrt(20)/2+1,2,-sqrt(20)/2+1)'],'需由符号区间推出对任意两参数成立的次序；验证取合法参数检验选项编码。')
add(24,'二次函数y=(x−2)²−9中，x₁、x₂、x₃对应函数值y₁、y₂、y₃。若0<x₁<1，2<x₂<3，x₃>5，则（ ）。',['y₁<y₂<y₃','y₂<y₁<y₃','y₃<y₁<y₂','y₂<y₃<y₁'],'B','0<x₁<1给出1<|x₁−2|<2，故−8<y₁<−5。2<x₂<3给出0<x₂−2<1，故−9<y₂<−8。x₃>5给出x₃−2>3，故y₃>0。因此y₂<y₁<y₃，严格端点不取。','抛物线顶点改为(2,−9)，相应区间改为(0,1)、(2,3)、(5,+∞)，保留区间函数值比较。',None,None,'需要分别分析三个自变量区间的完整值域。',spec={'kind':'ordering_values','values':{'y1':'(1/2-2)**2-9','y2':'(5/2-2)**2-9','y3':'(6-2)**2-9'},'option_orders':{'A':['y1','y2','y3'],'B':['y2','y1','y3'],'C':['y3','y1','y2'],'D':['y2','y3','y1']},'derivation':'完整区间证明见solution；机器对三个合法代表点的实际函数值排序作算术一致性核验。'})
add(25,'一次函数y=(a+2)x+a的图象经过第一、第三、第四象限，则二次函数y=ax²−4ax（ ）。',['有最大值−4a','有最大值4a','有最小值−4a','有最小值4a'],'A','直线经过第一、第三、第四象限，斜率a+2>0，截距a<0，所以−2<a<0。二次函数为a(x−2)²−4a，开口向下，最大值为−4a且x=2取得。a≠0。','直线斜率a+1改a+2，二次项的一次系数−a改−4a，保留直线象限确定开口再求极值。','(-(-4)/2,-(-4)**2/4, -1<0)',['(2,-4,True)','(2,4,True)','(2,-4,False)','(2,4,False)'],'需先推参数符号再配方；元组编码顶点横坐标、极值的a系数、是否最大值。')
add(26,'二次函数y=a(x−h)²+k（a≠0）满足x=2时y=2，x=8时y=8。下列说法一定正确的是（ ）。',['若h=3，则a>0','若h=4，则a<0','若h=6，则a>0','若h=7，则a>0'],'A','相减得6=a[(8−h)²−(2−h)²]=6a(10−2h)，故a=1/(10−2h)，h=5不可成立。h=3、4时a正，h=6、7时a负，只有A正确。','两已知点(1,1)、(6,6)改为(2,2)、(8,8)，重算参数符号分界。',None,None,'两点相减消去k，因式分解后判断a的符号。',spec={'kind':'statement_selection','target_truth':True,'statements':{'A':{'lhs':'1/(10-2*3)','op':'>','rhs':'0'},'B':{'lhs':'1/(10-2*4)','op':'<','rhs':'0'},'C':{'lhs':'1/(10-2*6)','op':'>','rhs':'0'},'D':{'lhs':'1/(10-2*7)','op':'>','rhs':'0'}},'derivation':'由两点条件得到a=1/(10−2h)，四个h均不导致分母零。'})
add(27,'抛物线y=x²+(m−2)x+m满足：当x=1时y<7；在整个区间x>3上，y随x增大而增大。m的取值范围为（ ）。',['−4<m<4','−4≤m<4','−4≤m≤4','m<4'],'B','x=1时y=2m−1<7，得m<4。开口向上，对称轴为x=(2−m)/2；要在整个x>3上递增，轴必须不超过3，所以m≥−4。轴恰为3时，在开区间x>3仍严格递增。综合为−4≤m<4。','一次系数m−1改m−2，函数值界4改7、递增区间x>2改x>3，保留两约束交集。','(2-2*3,(7+1)/2,True,False)',['(-4,4,False,False)','(-4,4,True,False)','(-4,4,True,True)','(0,4,False,False)'],'求对称轴并处理递增区间的闭端点；D编码只有上界无下界需另作结构说明。')
add(28,'点A(−2,y₁)、B(2,y₂)、C(5,y₃)在y=ax²−4ax+3（a>0）上，则（ ）。',['y₂<y₁<y₃','y₃<y₂<y₁','y₃<y₁<y₂','y₂<y₃<y₁'],'D','配方得y=a(x−2)²+3−4a。三点距轴x=2分别为4、0、3，因a>0，函数值按距离平方排序，所以y₂<y₃<y₁。a不为零，三值互异。','对称轴从1改2，三个横坐标改−2、2、5；保留距轴比较。',None,None,'配方识别对称轴，以到轴的距离平方比较。',spec={'kind':'ordering_values','values':{'y1':'(-2-2)**2','y2':'(2-2)**2','y3':'(5-2)**2'},'option_orders':{'A':['y2','y1','y3'],'B':['y3','y2','y1'],'C':['y3','y1','y2'],'D':['y2','y3','y1']},'derivation':'减去相同常数并除以正数a，保持序关系。'})
add(29,'x表示自变量，下列六个关系中反比例函数有几个？①y=3/(7x)；②y=2x；③y=−4x⁻¹；④xy=−5；⑤y=2/(x−1)；⑥y=0/x（x≠0）。',['2个','3个','4个','5个'],'B','①化为(3/7)/x、③为−4/x、④为−5/x，系数均非零，都是反比例函数。②是正比例；⑤分母含非零常数项；⑥系数为零不符合k≠0，故共3个。各式按自身分母非零的定义域。','修改各系数，移位分母改x−1，并把原非零0.4/x改为0/x以检验非零条件。','sum((3/7!=0,2==-1,-4!=0,-5!=0,-1==0,0!=0))',['2','3','4','5'],'须化为k/x并同时检验k非零与原定义域。')
add(30,'点A(−3,y₁)、B(2,y₂)都在反比例函数y=k/x（k≠0）上，则一定成立的是（ ）。',['3y₁+2y₂=0','2y₁+3y₂=0','3y₁−2y₂=0','2y₁−3y₂=0'],'A','由−3y₁=k=2y₂，得3y₁+2y₂=0。k≠0使两函数值非零，其他三个线性关系都不成立，且四个方程系数不成比例。','两个横坐标−2、1改为−3、2，保留xy=k消去参数。',None,None,'由两点的横纵坐标乘积相等得线性关系。',spec={'kind':'statement_selection','target_truth':True,'statements':{'A':{'lhs':'3*(-1/3)+2*(1/2)','op':'==','rhs':'0'},'B':{'lhs':'2*(-1/3)+3*(1/2)','op':'==','rhs':'0'},'C':{'lhs':'3*(-1/3)-2*(1/2)','op':'==','rhs':'0'},'D':{'lhs':'2*(-1/3)-3*(1/2)','op':'==','rhs':'0'}},'derivation':'所有等式齐次于非零k，除以k后取k=1计算，不损失一般性。'})
add(31,'反比例函数y=(m−√5)/x的图象位于第二、第四象限，则m可能为（ ）。',['√5','5/2','2','3'],'C','第二、第四象限对应k=m−√5<0，即m<√5。2²=4<5，故2可取；(5/2)²=25/4>5与3²>5，均大于√5；m=√5导致k=0，不是反比例函数。','√3改√5，候选值全部调整，保留象限确定系数符号与排除零。',None,None,'需比较含根号实数并排除系数零。',spec={'kind':'statement_selection','target_truth':True,'statements':{k:{'lhs':v,'op':'<','rhs':'sqrt(5)'} for k,v in zip('ABCD',['sqrt(5)','5/2','2','3'])},'derivation':'二、四象限要求非零系数为负。'})
add(32,'反比例函数y=−12/x上有A(−4,y₁)、B(6,y₂)。正确关系是（ ）。',['y₁−y₂=5','y₁−y₂=1','y₁+y₂=5','y₁+y₂=−1'],'A','y₁=−12/(−4)=3，y₂=−12/6=−2，所以差为5、和为1；四项中仅A正确。横坐标均非零。','函数系数−6改−12，两横坐标−3、3改−4、6，比较关系改为和差数值。','(-12/(-4))-(-12/6)',['5','1','3','-1'],'两次代入与正负数运算，实际难度为基础。',difficulty='基础')
add(33,'已知y₁=6x+t、y₂=3x²+6，x、t均为实数。对固定t，要求对所有实数x均有y₁≤y₂，且方程y₁=y₂恰有一个实数解。则t及该解为（ ）。',['t=3，x=1','t<3，x=1','t=6，x=1','t=3，x=−1'],'A','差y₂−y₁=3x²−6x+6−t=3(x−1)²+3−t。对所有x非负等价于t≤3；有相等点要求t≥3，故t=3，此时仅x=1相等。t<3时没有相等点，t>3时有两交点且不满足处处不等式。','原两固定函数改为含参数t的全实数不等式及唯一等号点，保留配方比较与方程根数。','(6-6**2/(4*3),6/(2*3))',['(3,1)','(2,1)','(6,1)','(3,-1)'],'需区分全称不等式与唯一交点条件，配方综合判断；实际中等。',difficulty='中等')
add(34,'小球高度h（m）与时间t（s）的关系为h=40t−5t²，0≤t≤8。判断：①落地时刻为t=8；②最高高度为80 m；③高度不低于60 m的总时长为4 s；④t=2与t=7时高度相等。正确结论个数为（ ）。',['1','2','3','4'],'C','h=5t(8−t)，首次抛出后落地t=8，①正确。配方h=80−5(t−4)²，最高80在t=4取得，②正确。h≥60等价于(t−4)²≤4，区间[2,6]在运动域内，时长4，③正确。h(2)=60而h(7)=35，④错误。共3个。','初速度30改40、运动域0≤t≤6改0≤t≤8；加入完整高度区间时长判断。','sum((40/5==8,40**2/(4*5)==80,2*sqrt((80-60)/5)==4,40*2-5*2**2==40*7-5*7**2))',['1','2','3','4'],'综合落地、顶点、二次不等式区间与值比较；实际中等。',difficulty='中等')
add(35,'抛物线y=a(x−2)(x−6)（a≠0）与x轴交于A(2,0)、B(6,0)。P₁、P₂是抛物线上不同于A、B的点，坐标横坐标分别为x₁、x₂，△P₁AB、△P₂AB面积分别为S₁、S₂。判断：①x₁>x₂+4时一定S₁>S₂；②x₁<4−x₂时一定S₁<S₂；③|x₁−4|>|x₂−4|>2时一定S₁>S₂；④|x₁−4|>|x₂+4|>2时一定S₁<S₂。所有正确结论为（ ）。',['①③','②③','只有③','③④'],'C','Sᵢ=2|a|·|(xᵢ−4)²−4|。③两距离都大于2，绝对值内为正，平方按距离严格增大，所以正确。①取x₁=5、x₂=−10，则5>−10+4，但面积因子3<192，错误。②取x₁=−10、x₂=1，满足−10<4−1，却有192>5，错误。④取x₁=12、x₂=−1，则8>3>2，却有60>21，错误。所有反例点均不等于根2、6，故仅③。','交点1、3改2、6，对称轴及距离阈值同步改4、2；保留面积绝对值比较与反例排除。','(abs((5-4)**2-4)>abs((-10-4)**2-4),abs((-10-4)**2-4)<abs((1-4)**2-4), 3**2-4> (5/2)**2-4,abs((12-4)**2-4)<abs((-1-4)**2-4))',['(True,False,True,False)','(False,True,True,False)','(False,False,True,False)','(False,False,True,True)'],'需推面积绝对值公式，证明全称结论并构造三条反例。')
add(36,'二次函数y=x²−2bx+2b²−12c经过不同两点A(3−b,m)、B(2b+c,m)，且图象与x轴有公共点，则b+c为（ ）。',['−3','1','3','6'],'C','等高不同两点关于轴x=b对称，所以(3−b)+(2b+c)=2b，得c=b−3。图象与x轴有公共点要求Δ=4b²−4(2b²−12c)=48c−4b²≥0，即b²≤12c。代入c=b−3得(b−6)²≤0，故b=6、c=3，b+c=9。此时A横坐标−3、B横坐标15，确不同，函数最低值为0，条件存在。','原3? 点常数1改3、常数项−4c改−12c，保留对称关系与判别式联合使参数唯一。','(12/2)+(12/2-3)',['-3','1','3','9'],'两点对称消元，再由判别式得到平方≤0与唯一参数；须回代验证存在。')
