add(37,'二次函数y=ax²+bx+c与x轴交于A(4,0)、B(−2,0)，与y轴交于C(0,m)，且−8<m<−4。判断：①a−c>0；②方程ax²+bx+c−6=0无实数根；③−2<b<−1；④(a+b+c)/(b−a)>0。错误结论个数为（ ）。',['1个','2个','3个','4个'],'A','y=a(x−4)(x+2)，所以b=−2a、c=−8a=m，1/2<a<1。①a−c=9a>0，正确。②原函数开口向上、最小值−9a<0，水平线y=6总有两个交点，错误。③−2<b<−1，正确。④a+b+c=−9a，b−a=−3a≠0，比值3>0，正确。因此仅1个错误。','根3、−1改4、−2，截距区间−4<m<−3改−8<m<−4，常数目标5改6；保留系数范围综合判断，删除非必要如图。','sum((not (9*(3/4)>0),not ((-2*(3/4))**2-4*(3/4)*(-8*(3/4)-6)<0),not (-2<-2*(3/4)<-1),not ((-9*(3/4))/(-3*(3/4))>0)))',['1','2','3','4'],'交点式推参数区间，判别式与分式符号四方面综合；算术取区间内a验证已由通式证明的结论。')
add(38,'二次函数y=(x−5)²与x轴的交点为（ ）。',['(−5,0)','(5,0)','(0,5)','(0,−5)'],'B','令y=0得(x−5)²=0，只得x=5（重根）。交点为(5,0)，只有一个交点。','顶点横坐标由−2改5，保留完全平方重根与交点。','(5,0)',['(-5,0)','(5,0)','(0,5)','(0,-5)'],'直接令函数值为零。')
add(39,'二次函数y=x²−4x+c的图象与x轴没有公共点，则c可能为（ ）。',['3','4','5','0'],'C','判别式Δ=16−4c<0，得c>4。四项仅5符合。c=4有一个公共点，不满足条件。','一次系数3改−4，候选常数修改并包含边界值4。',None,None,'由判别式判断无实根，排除等号边界。',spec={'kind':'statement_selection','target_truth':True,'statements':{k:{'lhs':f'16-4*({v})','op':'<','rhs':'0'} for k,v in zip('ABCD',[3,4,5,0])},'derivation':'无交点等价于严格负判别式。'})
add(40,'抛物线y=2x²−4x+2与x轴有几个公共点？',['0个','1个','2个','3个'],'B','y=2(x−1)²，令y=0仅得x=1，虽为二重根，但对应一个交点(1,0)。','原x²−4x+3改2x²−4x+2，引入零判别式边界。','(0==0)',['0','1','2','3'],'判断重根对应一个交点。')
