add(41,'抛物线y=x²−6x+8与x轴交于A、B，与y轴交于C，则△ABC的面积为（ ）。',['4','6','8','16'],'C','令y=0得(x−2)(x−4)=0，所以AB=2。C=(0,8)，到x轴的距离为8，面积=(1/2)×2×8=8。交点互异且截距不为零，三角形非退化。','根由1、3改为2、4，截距3改8，重算面积。','sqrt((-6)**2-4*8)*abs(8)/2',['4','6','8','16'],'求两类坐标轴交点并代入三角形面积。')
add(42,'点A(x₁,3)、B(x₂,−2)、C(x₃,6)在反比例函数y=12/x上，则x₁、x₂、x₃的大小关系为（ ）。',['x₁<x₂<x₃','x₂<x₃<x₁','x₃<x₁<x₂','x₂<x₁<x₃'],'B','x₁=12/3=4，x₂=12/(−2)=−6，x₃=12/6=2，所以x₂<x₃<x₁。三纵坐标均非零，三横坐标也非零。','系数8改12，三个纵坐标2、−1、4改3、−2、6，保留反求横坐标排序。',None,None,'由xy=k求横坐标再排序。',spec={'kind':'ordering_values','values':{'x1':'12/3','x2':'12/(-2)','x3':'12/6'},'option_orders':{'A':['x1','x2','x3'],'B':['x2','x3','x1'],'C':['x3','x1','x2'],'D':['x2','x1','x3']},'derivation':'由每点的非零纵坐标反求x。'})
add(43,'下列函数中，反比例函数是（ ）。',['y=−9x','y=−9/x（x≠0）','y=9/(x+2)（x≠−2）','y=0/x（x≠0）'],'B','反比例函数应为y=k/x且k≠0。B的k=−9，符合；A是正比例函数，C分母含常数2，D系数0，不符合。','从抽象名称辨认改为四个具体关系辨认，增加非零系数与移位分母干扰。',None,None,'应用反比例函数的定义。',spec={'kind':'inverse_function_forms','forms':{'A':{'type':'power','coefficient':-9,'exponent':1},'B':{'type':'power','coefficient':-9,'exponent':-1},'C':{'type':'linear_fraction','numerator':9,'x_coefficient':1,'constant':2},'D':{'type':'power','coefficient':0,'exponent':-1}},'derivation':'唯一非零系数乘x的−1次幂为B。'})
add(44,'点P(3,−5)在反比例函数y=−15/x上。利用图象关于原点的中心对称性，P的对称点为（ ）。',['(−3,5)','(3,5)','(−3,−5)','(5,−3)'],'A','关于原点的中心对称将(x,y)变为(−x,−y)，所以P的对称点为(−3,5)，且乘积−3×5=−15，确在原图象上。','给出具体反比例函数与点，将图象对称类别判断转为应用原点对称求点。','(-3,-(-5))',['(-3,5)','(3,5)','(-3,-5)','(5,-3)'],'直接使用中心对称的坐标规则。')
add(45,'反比例函数y=−7/x（x≠0）的两支图象分别位于（ ）。',['第一、第三象限','第二、第四象限','第一、第二象限','第三、第四象限'],'B','系数−7<0，x与y异号；x>0时y<0在第四象限，x<0时y>0在第二象限。坐标轴上没有点。','将k>0改为具体负系数−7，改变所处象限。','((-1,-7/(-1)),(1,-7/1))',['((1,7),(-1,-7))','((-1,7),(1,-7))','((1,7),(-1,7))','((-1,-7),(1,-7))'],'由系数符号判定横纵坐标同异号，元组用各象限对应坐标符号的实际点作特征。')
add(46,'点P在反比例函数y=−18/x上，过P分别向x轴、y轴作垂线，垂足为M、N。四边形OMPN（O为原点）的面积是（ ）。',['9','18','36','−18'],'B','设P=(x,y)，x、y均非零。矩形边长为|x|、|y|，面积=|xy|=|−18|=18，不随P位置改变。','将抽象|k|几何意义改为具体负系数−18对应矩形面积，明确垂足及四边形顺序。','abs(-18)',['9','18','36','-18'],'用xy=k与矩形面积绝对值。')
add(47,'抛物线y=(x−m)²+(m−2)的顶点在第一象限，则m满足（ ）。',['m>0','m>2','m≥2','0<m<2'],'B','顶点为(m,m−2)。第一象限要求m>0且m−2>0，合并m>2。m=2在x轴上，不能包含。','顶点纵坐标m+1改m−2，使两正坐标约束产生新分界。','(max(0,2),False)',['(0,False)','(2,False)','(2,True)','(0,2)'],'判断顶点两坐标严格为正并排除轴上边界。')
add(48,'关于x的二次函数y=kx²−4x−2与x轴有两个不同交点，则k范围为（ ）。',['k>−2','k≥−2且k≠0','k>−2且k≠0','k<−2'],'C','二次函数要求k≠0。判别式Δ=16+8k>0得k>−2，两条件同时成立。k=−2仅一交点，k=0退化为一次函数，均应排除。','一次系数−3改−4、常数−1改−2，保留正判别式与二次项非零双条件。','(-((-4)**2)/8,False,True)',['(-2,False,False)','(-2,True,True)','(-2,False,True)','(-2,True,False)'],'检验二次项非零并解严格判别式；元组为界值、包含界值、排除零。')
add(49,'将抛物线y=x²向左平移2个单位，再向下平移5个单位，所得函数为（ ）。',['y=(x−2)²−5','y=(x+2)²+5','y=(x−2)²+5','y=(x+2)²−5'],'D','左移2用x+2代替x，下移5再减5，得y=(x+2)²−5=x²+4x−1。','右移1、上移3改为左移2、下移5，保留平移方向与顶点式。','(1,2*2,2**2-5)',['(1,-4,-1)','(1,4,9)','(1,-4,9)','(1,4,-1)'],'直接使用平移公式；验证按二次、一次、常数系数编码。')
add(50,'a、b是方程x²+14x+1=0的两个实根，c、d是方程x²−11x+1=0的两个实根，则(a+c)(b+c)(a−d)(b−d)为（ ）。',['−75','75','−25','25'],'A','韦达定理给a+b=−14、ab=1、c+d=11、cd=1。由c²=11c−1、d²=11d−1，(a+c)(b+c)=1−14c+c²=−3c；(a−d)(b−d)=1+14d+d²=25d。乘积=−75cd=−75。两判别式196−4、121−4均正，实根条件成立。','两个一次系数20、−17改14、−11，保留韦达关系与根方程降幂。','(11-14)*(11+14)*1',['-75','75','-25','25'],'两组根和积与降幂消元，不能直接逐个求根。')
add(51,'抛物线y=x²+bx+c与x轴只有一个公共点，并经过A(m,n)、B(m−10,n)，则n为（ ）。',['10','20','25','100'],'C','唯一公共点说明抛物线为y=(x−h)²，顶点在x轴。两等高点横坐标相差10，对称轴h=m−5，每点距轴5，故n=5²=25。两点确不同，不依赖m的具体值。','两等高点间距8改10，保留零判别式与轴对称。','(10/2)**2',['10','20','25','100'],'结合唯一x轴交点与等高点中点求函数值。')
add(52,'质数a、b是整系数方程x²−25x+t=0的两个根，则b/a+a/b为（ ）。',['533/46','529/46','25/46','46/533'],'A','a+b=25为奇数，因此两个质数中恰有一个偶质数2，另一个是23（质数），所以ab=46，a²+b²=4+529=533，所求533/46。a、b正且非零，交换顺序不改变结果，t=46可取。','根和21改25，由2与19改为2与23，保留质数奇偶约束和韦达定理。','(2**2+(25-2)**2)/(2*(25-2))',['533/46','529/46','25/46','46/533'],'根和与质数奇偶性锁定两根，再求对称分式。')
add(53,'实数x、y满足xy−2x−2y=5，则x²+y²的最小值为（ ）。',['2','5','18','50'],'A','令s=x+y，则xy=2s+5。x、y为实数要求Δ=s²−4(2s+5)=(s−10)(s+2)≥0，故s≤−2或s≥10。x²+y²=s²−4s−10=(s−2)²−14：在s≤−2上最小为2，在s≥10上最小为50。取x=y=−1满足原式且平方和2，故全局最小2。','线性系数1改2、常数1改5，保留实根判别式限定和的两区间及全局最值。','min((-2-2)**2-14,(10-2)**2-14)',['2','5','18','50'],'以根判别式刻画可行和，再比较两个分支的端点最值并验证达到。')
add(54,'m<n，方程(x−m)(x−n)+9=0有两个不同实根a、b，a<b。四数的次序是（ ）。',['a<m<n<b','m<a<b<n','m<a<n<b','a<m<b<n'],'B','令h=(m+n)/2、d=(n−m)/2>0，方程为(x−h)²=d²−9。有两个不同实根要求d>3，根为h±√(d²−9)。因0<√(d²−9)<d，可知m=h−d<a<b<h+d=n。','常数2022改9，保留两个根位于m、n内侧的配方比较，并明确根互异。','(0,4-sqrt(4**2-9),4+sqrt(4**2-9),8)',['(4-sqrt(7),0,8,4+sqrt(7))','(0,4-sqrt(7),4+sqrt(7),8)','(0,4-sqrt(7),8,4+sqrt(7))','(4-sqrt(7),0,4+sqrt(7),8)'],'必须推实根存在的间距条件与四数严格次序；验证用合法m=0,n=8代表点编码。')
add(55,'某公园绿化面积原为500公顷，连续两年以相同年增长率x增长，两年后为605公顷，x>0。所列方程正确的是（ ）。',['500(1+x)²=605','500(1+2x)=605','500x²=605','500(1−x)²=605'],'A','第一年面积500(1+x)，第二年再乘(1+x)，故500(1+x)²=605。在x>0范围解得x=0.1；另一代数根−2.1不符合增长条件。','初始面积300改500、末面积363改605，保留两年复合增长并明确正增长。','(1,2,(500-605)/500)',['(1,2,-21/100)','(0,2,-21/100)','(1,0,-121/100)','(1,-2,-21/100)'],'从逐年增长写二次方程，元组为各式移至左侧后除500的系数。')
add(56,'方程3x²−6x+3=0的实数根情况是（ ）。',['没有实根','只有一个不同的实根（重根）','两个不同实根','三个不同实根'],'B','3x²−6x+3=3(x−1)²，故x₁=x₂=1，是重根，只有一个不同实根。二次系数3非零。','2x²+3x+1改3x²−6x+3，判别式改为0，考查重根边界。','2*((-6)**2-4*3*3>0)+((-6)**2-4*3*3==0)',['0','1','2','3'],'直接判别式或因式分解判断根数。')
add(57,'某零件的累计随机抽检数据如下：抽检100、500、1000、5000、10000件时，合格件数分别为87、442、881、4398、8802。抽样条件稳定，根据大量试验的频率，估计随机取一件合格的概率约为（ ）。',['0.50','0.88','0.99','1'],'B','累计合格频率为0.87、0.884、0.881、0.8796、0.8802，随样本增大稳定在0.88附近，所以概率约0.88。频率不是对每一次结果的确定保证，概率估计也不是精确等于0.8802。','把口罩数据改为零件并将稳定频率0.92附近改为0.88附近，保留大样本频率估计。','8802/10000',['0.50','0.88','0.99','1'],'需识别趋于稳定的频率而非小样本或必然事件；机器数值四舍五入一致性。',spec={'kind':'derived_value','derived_expr':'(8802/10000*100+1/2)//1/100','option_exprs':dict(zip('ABCD',['0.50','0.88','0.99','1'])),'derivation':'最后一项频率按百分位四舍五入为0.88，前四项检验稳定趋势。'})
add(58,'某运动员累计投篮次数为20、100、200、500、1000时，命中次数分别为15、73、145、361、720。训练条件稳定，估计一次投篮命中的概率约为（ ）。',['0.20','0.50','0.72','0.90'],'C','命中频率依次为0.75、0.73、0.725、0.722、0.720，稳定在0.72附近，因此估计命中概率约0.72。大量重复频率用于估计而不是保证下一次命中。','命中频率约0.80改为约0.72，调整全部投篮累计数据。','720/1000',['0.20','0.50','0.72','0.90'],'需联系多组频率随试验次数增加的稳定趋势。')
add(59,'10个同类产品中有7个正品、3个次品。随机一次抽取4个，不放回。下列事件必然发生的是（ ）。',['抽到4个正品','至少抽到1个正品','至少抽到1个次品','抽到2个正品和2个次品'],'B','次品只有3个，抽4个不可能全是次品，故至少有1个正品。全正品可从7正品中抽4个，说明C非必然；抽1正品3次品说明A、D非必然。','总数12改10、正品10改7、次品2改3，抽3改抽4，保留容量限制判断必然事件。','max(0,4-3)',['4','1','0','2'],'以次品最大容量推出正品最低数，给反例区分可能与必然。')
add(60,'袋中有4个黄球和若干白球，除颜色外完全相同。每次充分搅匀，随机摸1球后放回。十组各摸100次，摸到白球次数分别为59、61、58、62、60、60、61、59、63、57。估计白球数量为（ ）。',['4','5','6','8'],'C','白球累计600次、总1000次，估计概率为0.6。设白球数量w，则w/(w+4)≈0.6，解得w≈6。总球数正，估计为整数6；随机抽样频率并非精确证明球数。','黄球3改4，白球频率约0.4改0.6，保留概率模型反推个数。','4*(sum((59,61,58,62,60,60,61,59,63,57))/1000)/(1-sum((59,61,58,62,60,60,61,59,63,57))/1000)',['4','5','6','8'],'累计频率估计概率并解分式模型。')
add(61,'甲箱有30个红球和20个黑球；乙箱有45个红球、15个黑球、30个白球。球除颜色外无差别，各箱搅匀后分别随机摸1球。下列说法正确的是（ ）。',['甲箱摸红球概率小于乙箱','甲箱摸红球概率大于乙箱','两箱摸黑球概率相等','乙箱摸白球概率为1/2'],'B','甲红概率30/50=3/5，乙红45/90=1/2，所以甲更大。黑球概率分别20/50=2/5、15/90=1/6，不相等；乙白30/90=1/3而非1/2。各球等可能。','改两箱红黑白数量，保留同类事件概率与多种颜色分母比较。',None,None,'需正确计算两箱各自总数并比较概率。',spec={'kind':'statement_selection','target_truth':True,'statements':{'A':{'lhs':'30/(30+20)','op':'<','rhs':'45/(45+15+30)'},'B':{'lhs':'30/(30+20)','op':'>','rhs':'45/(45+15+30)'},'C':{'lhs':'20/(30+20)','op':'==','rhs':'15/(45+15+30)'},'D':{'lhs':'30/(45+15+30)','op':'==','rhs':'1/2'}},'derivation':'各箱均匀随机，概率为该颜色数量除本箱总数。'})
add(62,'五张卡片分别写着1、2、3、4、5，随机装入五个编号1、2、3、4、5的相同不透明盒子，每种装法等可能。只要至少一个盒号与内部数字相同即中奖，则中奖概率为（ ）。',['11/30','19/30','5/6','1/5'],'B','共有5!=120种排列。用容斥计至少一个对应相同的排列数：5·4!−C(5,2)·3!+C(5,3)·2!−C(5,4)·1!+1=120−60+20−5+1=76。概率76/120=19/30。重叠匹配按容斥处理，不能把五个匹配事件直接相加。','四个盒子改五个，保留随机排列、错排补集/容斥中奖概率。','(5*24-10*6+10*2-5+1)/(5*4*3*2*1)',['11/30','19/30','5/6','1/5'],'五对象排列与重叠事件计数，需完整容斥或错排递推。')
add(63,'每轮同时独立抛三枚均匀硬币。规定“公平”为甲乙每轮所得分的期望相等，不讨论先到某分数的获胜概率。下列四种计分规则中，不公平的是（ ）。',['正面个数为偶数甲得1分，奇数乙得1分','全正面甲得1分，全反面乙得1分，其余都不得分','全正面甲得7分，其余乙得1分','全正面甲得3分，其余乙得1分'],'D','三枚硬币共有8种等可能有序结果。A中正面个数为偶数有C(3,0)+C(3,2)=4种，奇数亦4种，期望同为1/2。B甲乙各仅1种得分，期望同为1/8。C甲期望7/8，乙7/8。D甲3/8而乙7/8，不相等，故D。四种规则的事件与收益均不同。','两枚改三枚；明确改成单轮得分期望公平，不能将源先到10分获胜公平与等期望视为等价；保留事件计数与公平性比较。',None,None,'需枚举三枚硬币结果与按得分加权比较；实际中等。',spec={'kind':'option_sign','target_sign':'negative','option_exprs':{'A':'(1+3)/8-(3+1)/8','B':'1/8-1/8','C':'7/8-7/8','D':'3/8-7/8'},'derivation':'四项甲期望减乙期望分别0、0、0、−1/2；唯一非零差为D，目标负差编码不公平项。'},difficulty='中等')
add(64,'8人参加象棋单循环赛，每两人赛1局，胜得2分、平各1分、负0分。第一名得分严格高于第二名，第二名得分严格高于其余6人。已知第二名得分等于最后4名得分之和，则第二名得分为（ ）。',['10','11','12','13'],'C','最后4名相互赛6局，每局总2分，因此其总分至少12，第二名至少12。每人赛7局，最多14；第二名若14则无人更高。若13则为6胜1平，得分更高的第一名须14分全胜，不可能与第二名平局，矛盾。因此只能12。存在构造：第一名胜所有人，第二名仅负第一名；第三、四名均胜最后4人且负前二，彼此任意赛；最后4名相互比赛且都负前4人，总分12，每人≤6，第三第四得8至10，故排名满足，第二名12。','人数12改8，最后5人改4人；明确前二名均为严格排名，保留总分下界与第二名上界夹逼及构造。','4*(4-1)',['10','11','12','13'],'须利用组内总分、严格名次上界排除13、14并构造可达例。')
add(65,'答对两道题才通关。第1题原有5项，已排除2个错项；第2题原有6项，尚未排除任何项。每题唯一正确，各次猜答独立且在剩余项中均匀随机。有3次求助，每次可去掉所选题的1个错项，也可不用完。下列策略使通关概率最大的是（ ）。',['第1题用2次，第2题用1次','第1题用1次，第2题用2次','3次都用于第2题','只用2次，均用于第1题'],'A','求助前剩3、6项。A剩1、5项，通关1/5；B剩2、4项，为1/8；C剩3、3项，为1/9；D剩1、6项，为1/6，故A最大。求助只删错项，各策略可行。其他用满3次的分配只有(2,1)、(1,2)、(0,3)，第一题最多可删2错项；少用求助不会提高概率，故A也为全局最优。','两题原4项改5、6项，已排除1项改2项，求助2次改3次，明确独立均匀猜答与求助可行上限。',None,None,'比较可行求助分配后的概率乘积，解释全局最优。',spec={'kind':'maximum_option_value','option_exprs':{'A':'1/(3-2)/(6-1)','B':'1/(3-1)/(6-2)','C':'1/3/(6-3)','D':'1/(3-2)/6'},'derivation':'每题正确概率为剩余选项数的倒数，独立相乘。'})
