def selfcheck():
    from verify_pilot_variants import check_spec
    from collections import Counter
    records=[]
    for n in range(1,71):
        q=Q[n];p=P[n-1];issues=[];detail={}
        try:
            assert q['parent_id']==p['id'] and q['family_id']==p['family_id']
            assert q['grade']==p['grade'] and q['module']==p['module']
            assert set(q['options'])==set('ABCD') and len(set(q['options'].values()))==4
            assert q['question']!=p['question'] and q['change_description']
            assert q['input_modality']=='text' and q['image_assets']==[]
            assert '如图' not in q['question']
            assert q['generation_metadata']['agent']=='finish_variants_g9'
            assert q['generation_metadata']['generated_at'].endswith('+08:00')
            assert q['status']=='variant_draft_pending_review'
            for value in [q['question'],*q['options'].values(),q['solution']]:
                assert not any(ord(c)<32 and c not in '\n\t\r' for c in value)
            matches,detail=check_spec(q['verification_spec'])
            assert matches==[q['answer']],f'{matches} != {q["answer"]}'
        except Exception as e:issues.append(str(e))
        records.append({'id':q['id'],'passed':not issues,'errors':issues,'detail':detail,'content_sha256':hashlib.sha256(json.dumps({k:q[k] for k in ['question','options','answer','solution']},ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()})
    report={'agent':'finish_variants_g9','scope':'70件生成者结构与safe AST算术自检。一般命题的全称性、原题关系及语义编码由完整推导说明，机器核验部分仅为代表点/反例一致性，非独立复核或正式批准。','count':70,'passed':sum(r['passed'] for r in records),'failed':sum(not r['passed'] for r in records),'difficulty':dict(Counter(q['difficulty'] for q in Q.values())),'records':records}
    (BASE/'selfcheck_g9.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({k:v for k,v in report.items() if k!='records'},ensure_ascii=False))
    for r in records:
        if r['errors']:print(r['id'],r['errors'])
selfcheck()
